// HasConversation applies the HasEdge predicate on the "conversation" edge.
func HasConversation() predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ConversationTable, ConversationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasConversationWith applies the HasEdge predicate on the "conversation" edge with a given conditions (other predicates).
func HasConversationWith(preds ...predicate.EmailConversation) predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(func(s *sql.Selector) {
		step := newConversationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasMessage applies the HasEdge predicate on the "message" edge.
func HasMessage() predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MessageTable, MessageColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMessageWith applies the HasEdge predicate on the "message" edge with a given conditions (other predicates).
func HasMessageWith(preds ...predicate.InboundEmailMessage) predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(func(s *sql.Selector) {
		step := newMessageStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EmailIntakeAnalysis) predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EmailIntakeAnalysis) predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EmailIntakeAnalysis) predicate.EmailIntakeAnalysis {
	return predicate.EmailIntakeAnalysis(sql.NotPredicates(p))
}
